class SaldoInsuficiente(Exception):
    pass

def retirar(saldo, monto):
    if monto > saldo:
        raise SaldoInsuficiente(f"Faltan {monto - saldo}")
    return saldo - monto

try:
    retirar(50, 80)
except SaldoInsuficiente as e:
    print("Error:", e)

